local BalanceScaleMaker = {}
local PRODUCTS = {
    iron_balance = { name = "Železna tehtnica", ironCost = 2, woodCost = 1, time = 3, cost = 25, precision = 50, description = "Železna tehtnica za trgovino." },
    brass_balance = { name = "Medeninasta tehtnica", brassCost = 2, woodCost = 1, time = 4, cost = 55, precision = 65, prestige = 2, description = "Medeninasta tehtnica za trgovce." },
    silver_balance = { name = "Srebrna tehtnica", silverCost = 2, brassCost = 1, time = 6, cost = 130, precision = 78, prestige = 5, happiness = 1, description = "Srebrna tehtnica za zlatarje." },
    silver_beam_balance = { name = "Srebrnokljuna tehtnica", silverCost = 2, goldCost = 1, brassCost = 1, time = 9, cost = 320, precision = 88, prestige = 11, happiness = 2, description = "Tehtnica s srebrnim kljunom za plemiče." },
    gold_trim_balance = { name = "Zlatorobna tehtnica", goldCost = 1, silverCost = 1, brassCost = 1, jewelCost = 1, time = 12, cost = 700, precision = 94, prestige = 20, happiness = 4, description = "Zlatorobna tehtnica za visoke plemiče." },
    royal_grand_balance = { name = "Kraljevski veliki tehtnica", goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, brassCost = 1, time = 17, cost = 1800, precision = 100, prestige = 42, happiness = 9, description = "Velika kraljevska tehtnica z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Tehtničarska delavnica", cost = { gold = 260, wood = 130, stone = 250 }, upkeep = 6, qualityBonus = 5 },
    calibration_room = { name = "Kalibrirnica", cost = { gold = 900, wood = 250, stone = 450, iron = 8 }, upkeep = 22, qualityBonus = 18 },
    precision_room = { name = "Natančnostna soba", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, steel = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_scale_atelier = { name = "Kraljevski atelje tehtnic", cost = { gold = 9200, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 40 },
}
BalanceScaleMaker.ironStock = 14; BalanceScaleMaker.brassStock = 12; BalanceScaleMaker.woodStock = 14; BalanceScaleMaker.silverStock = 8; BalanceScaleMaker.goldStock = 6; BalanceScaleMaker.jewelStock = 6; BalanceScaleMaker.pearlStock = 4
BalanceScaleMaker.productStock = {}; BalanceScaleMaker.buildings = {}; BalanceScaleMaker.maker = nil; BalanceScaleMaker.activeMaking = {}; BalanceScaleMaker.totalProducts = 0; BalanceScaleMaker.dayTimer = 0
function BalanceScaleMaker.init() BalanceScaleMaker.ironStock=14; BalanceScaleMaker.brassStock=12; BalanceScaleMaker.woodStock=14; BalanceScaleMaker.silverStock=8; BalanceScaleMaker.goldStock=6; BalanceScaleMaker.jewelStock=6; BalanceScaleMaker.pearlStock=4; BalanceScaleMaker.productStock={}; BalanceScaleMaker.buildings={}; BalanceScaleMaker.maker=nil; BalanceScaleMaker.activeMaking={}; BalanceScaleMaker.totalProducts=0; BalanceScaleMaker.dayTimer=0; print("[BalanceScaleMaker] Royal Balance Scale Maker System initialized (6 products, 4 buildings)") end
function BalanceScaleMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BalanceScaleMaker.maker={name=n or ("Tehtničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtničar najet: %s (spretnost: %d)",BalanceScaleMaker.maker.name,s),"success") end; return true end
function BalanceScaleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BalanceScaleMaker.build(id) local ok,e=BalanceScaleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BalanceScaleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BalanceScaleMaker.getQualityBonus() local b=0; for _,bd in ipairs(BalanceScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BalanceScaleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BalanceScaleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and BalanceScaleMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.woodCost and BalanceScaleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and BalanceScaleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BalanceScaleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BalanceScaleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BalanceScaleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BalanceScaleMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BalanceScaleMaker.maker then return false,"Potreben tehtničar" end; return true end
function BalanceScaleMaker.make(pt,qty) qty=qty or 1; local ok,e=BalanceScaleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BalanceScaleMaker.ironStock=BalanceScaleMaker.ironStock-d.ironCost*qty end; if d.brassCost then BalanceScaleMaker.brassStock=BalanceScaleMaker.brassStock-d.brassCost*qty end; if d.woodCost then BalanceScaleMaker.woodStock=BalanceScaleMaker.woodStock-d.woodCost*qty end; if d.silverCost then BalanceScaleMaker.silverStock=BalanceScaleMaker.silverStock-d.silverCost*qty end; if d.goldCost then BalanceScaleMaker.goldStock=BalanceScaleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BalanceScaleMaker.jewelStock=BalanceScaleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BalanceScaleMaker.pearlStock=BalanceScaleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BalanceScaleMaker.maker then t=math.max(1,t-math.floor(BalanceScaleMaker.maker.skill/12)) end; table.insert(BalanceScaleMaker.activeMaking,{id="balance_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,precision=d.precision or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BalanceScaleMaker.completeMaking(m) local q=1.0+(BalanceScaleMaker.getQualityBonus()/100); if BalanceScaleMaker.maker then q=q+(BalanceScaleMaker.maker.skill/180) end; q=math.min(2.0,q); BalanceScaleMaker.productStock[m.productType]=(BalanceScaleMaker.productStock[m.productType] or 0)+m.quantity; BalanceScaleMaker.totalProducts=BalanceScaleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BalanceScaleMaker.maker then BalanceScaleMaker.maker.itemsMade=BalanceScaleMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BalanceScaleMaker.maker.skill=math.min(100,BalanceScaleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"balance.completed",{productName=m.productName,precision=m.precision}) end end
function BalanceScaleMaker.update(dt) if not _G.state then return end; BalanceScaleMaker.dayTimer=BalanceScaleMaker.dayTimer+dt; if BalanceScaleMaker.dayTimer>=30 then BalanceScaleMaker.dayTimer=0; for i=#BalanceScaleMaker.activeMaking,1,-1 do local m=BalanceScaleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BalanceScaleMaker.completeMaking(m); table.remove(BalanceScaleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BalanceScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BalanceScaleMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BalanceScaleMaker.getStats() return {ironStock=BalanceScaleMaker.ironStock,brassStock=BalanceScaleMaker.brassStock,woodStock=BalanceScaleMaker.woodStock,silverStock=BalanceScaleMaker.silverStock,goldStock=BalanceScaleMaker.goldStock,jewelStock=BalanceScaleMaker.jewelStock,pearlStock=BalanceScaleMaker.pearlStock,productStock=BalanceScaleMaker.productStock,numBuildings=#BalanceScaleMaker.buildings,hasMaker=BalanceScaleMaker.maker~=nil,makerName=BalanceScaleMaker.maker and BalanceScaleMaker.maker.name or "—",makerSkill=BalanceScaleMaker.maker and BalanceScaleMaker.maker.skill or 0,activeMaking=#BalanceScaleMaker.activeMaking,totalProducts=BalanceScaleMaker.totalProducts} end
return BalanceScaleMaker
